import { maybeInterval } from '../helpers/autoTicks.js';
import { resolveChannel } from '../helpers/resolve.js';
/**
 * Derives interval channels x1 and x2 from the x channel and interval channel.
 */
export function intervalX(args) {
    return interval('x', args);
}
/**
 * Derives interval channels y1 and y2 from the y channel and interval channel.
 */
export function intervalY(args) {
    return interval('y', args);
}
function interval(dim, { data, ...options }) {
    if (options.interval &&
        options[dim] &&
        options[`${dim}1`] == null &&
        options[`${dim}2`] == null) {
        // derive x1 and x2 from x+interval
        const interval = maybeInterval(options.interval);
        const newData = data.map((row) => {
            const val = resolveChannel(dim, row, options);
            return {
                ...row,
                [`__${dim}1`]: interval.floor(val),
                [`__${dim}2`]: interval.offset(interval.floor(val))
            };
        });
        return {
            data: newData,
            // set default inset
            [`inset${dim === 'x' ? 'Right' : 'Bottom'}`]: 1,
            ...options,
            [`${dim}1`]: `__${dim}1`,
            [`${dim}2`]: `__${dim}2`
        };
    }
    return { data, ...options };
}
